import{_ as i,o as e,c as s,a0 as n}from"./chunks/framework.DCluYYrN.js";const u=JSON.parse('{"title":"App Profile","description":"","frontmatter":{},"headers":[],"relativePath":"id_ID/guide/app-profile.md","filePath":"id_ID/guide/app-profile.md"}'),t={name:"id_ID/guide/app-profile.md"};function k(p,a,l,d,r,o){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="app-profile" tabindex="-1">App Profile <a class="header-anchor" href="#app-profile" aria-label="Permalink to &quot;App Profile&quot;">​</a></h1><p>App Profile adalah mekanisme yang disediakan KernelSU untuk menyesuaikan konfigurasi beragam aplikasi.</p><p>Untuk aplikasi yang diberi izin root (misalnya dapat memakai <code>su</code>), App Profile juga dapat disebut Root Profile. Ia memungkinkan kita menyesuaikan <code>uid</code>, <code>gid</code>, <code>groups</code>, <code>capabilities</code>, dan aturan <code>SELinux</code> dari perintah <code>su</code>, sehingga hak istimewa pengguna root dapat dibatasi. Contohnya, hanya memberikan izin jaringan kepada aplikasi firewall sambil menolak izin akses berkas, atau memberikan izin shell alih-alih akses root penuh untuk aplikasi pembeku: <strong>menjaga kekuatan agar tetap terkungkung dalam prinsip least privilege.</strong></p><p>Untuk aplikasi biasa tanpa izin root, App Profile dapat mengendalikan bagaimana kernel dan sistem modul bersikap terhadap aplikasi tersebut. Misalnya, App Profile bisa menentukan apakah perubahan yang disebabkan oleh modul harus tetap terlihat. Kernel dan sistem modul kemudian dapat membuat keputusan berdasarkan konfigurasi ini, seperti melakukan operasi serupa “menyembunyikan”.</p><div class="tip custom-block"><p class="custom-block-title">tip</p><p>Anda dapat mengaktifkan flag <code>NO_NEW_PRIVS</code> di <code>App Profile</code> kustom Anda.</p><p>Ini mencegah proses tersebut keluar dan meningkatkan hak akses lagi melalui perintah <code>su</code>.</p><p>Namun, flag ini <strong>hanya</strong> mencegah KernelSU meningkatkan hak akses untuk proses tersebut; proses tersebut masih dapat keluar menggunakan mekanisme Linux lainnya.</p><p>Oleh karena itu, harap berhati-hati dengan pengaturan izin Anda.</p></div><h2 id="root-profile" tabindex="-1">Root Profile <a class="header-anchor" href="#root-profile" aria-label="Permalink to &quot;Root Profile&quot;">​</a></h2><h3 id="uid-gid-dan-groups" tabindex="-1">UID, GID, dan Groups <a class="header-anchor" href="#uid-gid-dan-groups" aria-label="Permalink to &quot;UID, GID, dan Groups&quot;">​</a></h3><p>Di sistem Linux ada dua konsep: pengguna dan grup. Setiap pengguna memiliki user ID (UID), dan seorang pengguna bisa menjadi anggota banyak grup yang masing-masing memiliki group ID (GID). ID inilah yang dipakai untuk mengenali pengguna di sistem dan menentukan sumber daya apa yang boleh mereka akses.</p><p>Pengguna dengan UID 0 disebut pengguna root, dan grup dengan GID 0 disebut grup root. Grup root biasanya memiliki hak istimewa tertinggi dalam sistem.</p><p>Dalam sistem Android, tiap aplikasi bertindak sebagai pengguna terpisah (kecuali pada kasus shared UID) dengan UID unik. Misalnya <code>0</code> adalah root, <code>1000</code> adalah <code>system</code>, <code>2000</code> adalah shell ADB, dan UID dari <code>10000</code> hingga <code>19999</code> mewakili aplikasi biasa.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>UID yang dimaksud di sini berbeda dengan konsep multi-user atau work profile di Android. Work profile sebenarnya diimplementasikan dengan mempartisi rentang UID. Contohnya, 10000-19999 adalah pengguna utama, sementara 110000-119999 adalah work profile. Setiap aplikasi biasa di dalamnya tetap mempunyai UID unik.</p></div><p>Setiap aplikasi dapat memiliki beberapa grup, dengan GID sebagai grup utama yang biasanya sama dengan UID. Grup lain disebut grup tambahan (supplementary groups). Sejumlah izin dikendalikan oleh keanggotaan grup, misalnya izin akses jaringan atau Bluetooth.</p><p>Sebagai contoh, apabila kita menjalankan perintah <code>id</code> di shell ADB, hasilnya mungkin seperti ini:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">oriole:/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">id</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">uid</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shell</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) gid</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shell</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) groups</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">2000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">shell</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1004</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1007</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1011</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1015</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdcard_rw</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1028</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdcard_r</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1078</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ext_data_rw</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,1079</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ext_obb_rw</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,3001</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">net_bt_admin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,3002</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">net_bt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,3003</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">inet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,3006</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">net_bw_stats</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,3009</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">readproc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,3011</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uhid</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,3012</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">readtracefs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) context</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">u:r:shell:s0</span></span></code></pre></div><p>Di sini UID-nya <code>2000</code>, dan GID (ID grup utama) juga <code>2000</code>. Selain itu ia berada di beberapa grup tambahan seperti <code>inet</code> (boleh membuat soket <code>AF_INET</code> dan <code>AF_INET6</code>, artinya boleh mengakses jaringan) dan <code>sdcard_rw</code> (boleh baca/tulis kartu SD).</p><p>Root Profile milik KernelSU memungkinkan kita menyesuaikan UID, GID, dan grup untuk proses root setelah menjalankan <code>su</code>. Misalnya, Root Profile sebuah aplikasi root dapat mengatur UID menjadi <code>2000</code>, sehingga ketika menggunakan <code>su</code>, hak sebenarnya setara dengan shell ADB. Kita juga dapat menghapus grup <code>inet</code> agar perintah <code>su</code> tidak bisa mengakses jaringan.</p><div class="tip custom-block"><p class="custom-block-title">CATATAN</p><p>App Profile hanya mengendalikan hak proses root setelah menggunakan <code>su</code>, bukan izin asli aplikasi. Jika aplikasi meminta izin akses jaringan, ia tetap dapat mengakses jaringan meski tidak menggunakan <code>su</code>. Menghapus grup <code>inet</code> dari <code>su</code> hanya membuat <code>su</code> tidak bisa mengakses jaringan.</p></div><p>Root Profile dipaksakan oleh kernel dan tidak bergantung pada itikad aplikasi root, berbeda dengan mengganti pengguna atau grup secara manual melalui <code>su</code>. Pemberian izin <code>su</code> sepenuhnya berada di tangan pengguna, bukan pengembang.</p><h3 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h3><p>Capabilities adalah mekanisme pemisahan hak istimewa di Linux.</p><p>Untuk keperluan pemeriksaan izin, implementasi <code>UNIX</code> tradisional membedakan dua jenis proses: proses istimewa (effective UID <code>0</code>, disebut superuser atau root) dan proses biasa (effective UID bukan nol). Proses istimewa melewati semua pemeriksaan izin kernel, sedangkan proses biasa tunduk pada pemeriksaan penuh berdasarkan kredensial proses (biasanya effective UID, effective GID, dan daftar grup tambahan).</p><p>Sejak Linux 2.2, hak istimewa yang biasanya dimiliki superuser dipecah menjadi unit-unit terpisah yang disebut capability, dan masing-masing dapat diaktifkan atau dinonaktifkan secara independen.</p><p>Setiap capability mewakili satu atau lebih hak. Misalnya, <code>CAP_DAC_READ_SEARCH</code> mewakili kemampuan melewati pemeriksaan izin untuk membaca berkas serta izin baca dan eksekusi direktori. Jika seorang pengguna dengan effective UID <code>0</code> (root) tidak memiliki capability <code>CAP_DAC_READ_SEARCH</code> atau capability di atasnya, maka meskipun ia root ia tidak bisa sembarang membaca berkas.</p><p>Root Profile KernelSU memungkinkan kita menyesuaikan capability proses root setelah menjalankan <code>su</code>, sehingga yang diberikan hanyalah “hak root parsial”. Berbeda dengan UID dan GID di atas, beberapa aplikasi root memang membutuhkan UID <code>0</code> setelah memakai <code>su</code>. Pada kasus seperti ini, membatasi capability pengguna root dengan UID <code>0</code> dapat membatasi operasi yang boleh dilakukan.</p><div class="tip custom-block"><p class="custom-block-title">SANGAT DISARANKAN</p><p>Dokumentasi resmi capability Linux <a href="https://man7.org/linux/man-pages/man7/capabilities.7.html" target="_blank" rel="noreferrer">dapat dibaca di sini</a> dan menjelaskan detail hak yang diwakili tiap capability. Jika Anda ingin menyesuaikan capability, sangat disarankan membaca dokumen ini terlebih dahulu.</p></div><h3 id="selinux" tabindex="-1">SELinux <a class="header-anchor" href="#selinux" aria-label="Permalink to &quot;SELinux&quot;">​</a></h3><p>SELinux adalah mekanisme Mandatory Access Control (MAC) yang sangat kuat. Ia beroperasi berdasarkan prinsip <strong>default deny</strong>: tindakan apa pun yang tidak diizinkan secara eksplisit akan ditolak.</p><p>SELinux memiliki dua mode global:</p><ol><li>Mode Permissive: penolakan hanya dicatat di log, tidak ditegakkan.</li><li>Mode Enforcing: penolakan dicatat dan ditegakkan.</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Android modern sangat bergantung pada SELinux untuk menjaga keamanan sistem secara keseluruhan. Sangat disarankan untuk tidak memakai sistem kustom yang berjalan dalam mode “Permissive”, karena hampir tidak menawarkan keuntungan dibanding sistem yang sepenuhnya terbuka.</p></div><p>Menjelaskan SELinux secara tuntas sangatlah kompleks dan berada di luar cakupan dokumen ini. Disarankan mempelajari cara kerjanya melalui sumber berikut:</p><ol><li><a href="https://en.wikipedia.org/wiki/Security-Enhanced_Linux" target="_blank" rel="noreferrer">Wikipedia</a></li><li><a href="https://www.redhat.com/en/topics/linux/what-is-selinux" target="_blank" rel="noreferrer">Red Hat: What Is SELinux?</a></li><li><a href="https://wiki.archlinux.org/title/SELinux" target="_blank" rel="noreferrer">ArchLinux: SELinux</a></li></ol><p>Root Profile KernelSU memungkinkan kita menyesuaikan konteks SELinux dari proses root setelah menjalankan <code>su</code>. Kita bisa menetapkan aturan kontrol akses khusus untuk konteks ini sehingga hak root dapat diatur secara sangat granular.</p><p>Dalam skenario umum, ketika sebuah aplikasi menjalankan <code>su</code>, prosesnya berpindah ke domain SELinux dengan <strong>akses tidak terbatas</strong>, seperti <code>u:r:ksu:s0</code>. Melalui Root Profile, domain ini bisa diganti menjadi domain kustom seperti <code>u:r:app1:s0</code>, lalu serangkaian aturan dapat ditetapkan untuk domain tersebut:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">enforce</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">typeattribute</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mlstrustedsubject</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">allow</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> app1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> *</span></span></code></pre></div><p>Perlu dicatat, aturan <code>allow app1 * * *</code> di atas hanya untuk contoh. Dalam praktiknya aturan ini tidak boleh digunakan secara luas karena hampir sama saja dengan mode Permissive.</p><h3 id="eskalasi" tabindex="-1">Eskalasi <a class="header-anchor" href="#eskalasi" aria-label="Permalink to &quot;Eskalasi&quot;">​</a></h3><p>Jika konfigurasi Root Profile tidak ditetapkan dengan benar, skenario eskalasi bisa terjadi. Pembatasan yang diberikan App Profile bisa gagal tanpa sengaja.</p><p>Sebagai contoh, apabila Anda memberikan izin root kepada pengguna shell ADB (kasus yang cukup umum) dan kemudian memberikan izin root kepada aplikasi biasa, namun mengonfigurasi Root Profile aplikasi tersebut dengan UID 2000 (UID milik shell ADB), aplikasi itu bisa mendapatkan akses root penuh dengan menjalankan perintah <code>su</code> dua kali:</p><ol><li>Eksekusi <code>su</code> pertama akan tunduk pada App Profile dan mengubah UID menjadi <code>2000</code> (shell ADB) alih-alih <code>0</code> (root).</li><li>Eksekusi <code>su</code> kedua, karena UID-nya sudah <code>2000</code> dan UID <code>2000</code> (shell ADB) memang diberikan akses root pada konfigurasi, maka aplikasi itu akan memperoleh hak root penuh.</li></ol><div class="warning custom-block"><p class="custom-block-title">CATATAN</p><p>Perilaku ini sepenuhnya sesuai ekspektasi dan bukan bug. Karena itu kami menyarankan hal berikut:</p><p>Jika Anda benar-benar perlu memberikan izin root kepada ADB (misalnya sebagai pengembang), jangan mengubah UID menjadi <code>2000</code> saat mengonfigurasi Root Profile. Gunakan <code>1000</code> (system) agar lebih aman.</p></div><h2 id="non-root-profile" tabindex="-1">Non-root profile <a class="header-anchor" href="#non-root-profile" aria-label="Permalink to &quot;Non-root profile&quot;">​</a></h2><h3 id="umount-modules" tabindex="-1">Umount modules <a class="header-anchor" href="#umount-modules" aria-label="Permalink to &quot;Umount modules&quot;">​</a></h3><p>KernelSU menyediakan mekanisme systemless untuk memodifikasi partisi sistem dengan memasang OverlayFS. Namun beberapa aplikasi peka terhadap perilaku ini. Dalam kasus tersebut, kita dapat membongkar (umount) modul yang dimuat di aplikasi tertentu dengan mengaktifkan opsi “Umount modules”.</p><p>Selain itu, antarmuka pengaturan KernelSU Manager menyediakan opsi “Umount modules by default”. Secara bawaan opsi ini <strong>aktif</strong>, artinya KernelSU atau modul tertentu akan membongkar modul untuk aplikasi ini kecuali ada pengaturan tambahan. Jika Anda tidak menginginkan perilaku ini atau jika aplikasi tertentu terpengaruh, ada dua pendekatan:</p><ol><li>Biarkan “Umount modules by default” tetap aktif dan nonaktifkan opsi “Umount modules” di App Profile untuk aplikasi yang memang perlu memuat modul (berperan sebagai daftar putih).</li><li>Nonaktifkan “Umount modules by default” lalu aktifkan opsi “Umount modules” di App Profile hanya untuk aplikasi yang harus dibongkar modulnya (berperan sebagai daftar hitam).</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Pada perangkat dengan kernel versi 5.10 ke atas, kernel akan membongkar modul tanpa tindakan tambahan. Namun di perangkat dengan kernel di bawah 5.10, opsi ini hanya berupa konfigurasi dan KernelSU sendiri tidak mengambil tindakan apa pun. Jika ingin memakai opsi “Umount modules” pada kernel sebelum 5.10 Anda harus backport fungsi <code>path_umount</code> di <code>fs/namespace.c</code>. Anda bisa menemukan info lebih lanjut di bagian akhir halaman <a href="https://kernelsu.org/guide/how-to-integrate-for-non-gki.html#how-to-backport-path_umount" target="_blank" rel="noreferrer">Integrate for non-GKI devices</a>. Beberapa modul seperti Zygisksu juga memakai opsi ini untuk menentukan apakah modul perlu dibongkar.</p></div>`,47)])])}const g=i(t,[["render",k]]);export{u as __pageData,g as default};
